from typing import Any, Iterator
import csv
import io
import os

REQUIRED_COLUMNS = ('name', 'email')
MAX_ROWS = 10000
MAX_EMAIL_LENGTH = 254


def _cell(value: Any) -> str:
    if value is None:
        return ''
    if isinstance(value, float) and value.is_integer():
        value = int(value)
    return str(value).strip()


def _read_csv(data: bytes) -> tuple[list[str], Iterator[tuple[int, dict]]]:
    text = data.decode('utf-8-sig')
    reader = csv.DictReader(io.StringIO(text))
    header = [h.strip().lstrip('\ufeff').lower() for h in reader.fieldnames or []]
    reader.fieldnames = header

    def rows() -> Iterator[tuple[int, dict]]:
        for row in reader:
            yield reader.line_num, row

    return header, rows()


def _read_xlsx(data: bytes) -> tuple[list[str], Iterator[tuple[int, dict]]]:
    from openpyxl import load_workbook

    workbook = load_workbook(io.BytesIO(data), read_only=True, data_only=True)
    sheet = workbook.active
    iterator = sheet.iter_rows(values_only=True)
    first = next(iterator, None)
    header = [_cell(h).lower() for h in first or []]

    def rows() -> Iterator[tuple[int, dict]]:
        for line, values in enumerate(iterator, 2):
            if all(v is None or _cell(v) == '' for v in values):
                continue
            row = {header[i]: values[i] for i in range(min(len(header), len(values))) if header[i]}
            if any(_cell(v) for v in values[len(header):]):
                row[None] = True
            yield line, row

    return header, rows()


def import_users(data: bytes, filename: str, max_rows: int = MAX_ROWS) -> tuple[list[dict[str, Any]], list[dict[str, Any]]]:
    """Validate an uploaded users export (.csv or .xlsx).

    Returns (valid_users, errors). Every invalid row is reported as
    {"row": <line/row number in the file>, "errors": [reasons...]}; validation
    never stops at the first error. Row values are never echoed in messages.
    """
    ext = os.path.splitext(filename)[1].lower()
    try:
        if ext == '.csv':
            header, rows = _read_csv(data)
        elif ext in ('.xlsx', '.xlsm'):
            header, rows = _read_xlsx(data)
        else:
            return [], [{'row': 1, 'errors': ['unsupported file type; use .xlsx or .csv']}]
    except Exception:
        return [], [{'row': 1, 'errors': ['file could not be read']}]
    missing = [c for c in REQUIRED_COLUMNS if c not in header]
    if missing:
        return [], [{'row': 1, 'errors': [f"missing columns: {', '.join(missing)}"]}]
    valid, errors, seen = [], [], set()
    try:
        for count, (line, row) in enumerate(rows, 1):
            if count > max_rows:
                errors.append({'row': line, 'errors': [f'more than {max_rows} rows; stopped']})
                break
            name = _cell(row.get('name'))
            email = _cell(row.get('email')).lower()
            age_raw = _cell(row.get('age'))
            local, _, domain = email.partition('@')
            problems = [] if name else ['name is required']
            if None in row:
                problems.append('too many fields')
            if len(email) > MAX_EMAIL_LENGTH or not local or ' ' in email or '@' in domain or '.' not in domain.strip('.'):
                problems.append('email is invalid')
            elif email in seen:
                problems.append('duplicate email')
            if age_raw and not (age_raw.isdigit() and int(age_raw) <= 150):
                problems.append('age must be a whole number from 0 to 150')
            if problems:
                errors.append({'row': line, 'errors': problems})
            else:
                seen.add(email)
                valid.append({'name': name, 'email': email, 'age': int(age_raw) if age_raw else None})
    except Exception:
        errors.append({'row': 1, 'errors': ['file could not be read']})
    return valid, errors

